// Active project ids from the data table (labels are UI-only in Lokalise, so
// this table is the only source of truth for the "active" label).
const activeRows = $('Get Active Projects').all().map(i => i.json);
const activeIds = new Set(activeRows.map(r => r.project_id));
const nameById = new Map(activeRows.map(r => [r.project_id, r.project_name]));

const resp = $('Fetch Projects').first().json;
const body = resp.body || resp;
if (!Array.isArray(body.projects)) {
  throw new Error('Lokalise /projects returned no projects array - check the token and response shape');
}

// Not real target languages: source EN plus pseudo-locales.
const EXCLUDE_ISO = new Set(['en', 'pst', 'ps', 'cus', 'pt_old']);

const fetched = new Map(body.projects.map(p => [p.project_id, p]));
const incomplete = [];
const missing = [];

for (const pid of activeIds) {
  const p = fetched.get(pid);
  if (!p) { missing.push(nameById.get(pid) || pid); continue; }

  const langs = ((p.statistics || {}).languages || [])
    .filter(l => !EXCLUDE_ISO.has(l.language_iso))
    .filter(l => l.progress < 100)
    .map(l => ({ iso: l.language_iso, progress: l.progress }))
    .sort((a, b) => a.progress - b.progress);

  if (langs.length === 0) continue;

  incomplete.push({
    project_id: pid,
    name: p.name,
    worst: langs[0].progress,
    languages: langs,
    url: 'https://app.lokalise.com/project/' + pid + '/'
  });
}

// Alphabetical, as in the nightly QA report - leading punctuation stripped so
// '"myevisa.com"' sorts under m, not above everything.
incomplete.sort(function (a, b) {
  return a.name.replace(/^[^A-Za-z0-9]+/, '').toLowerCase()
    .localeCompare(b.name.replace(/^[^A-Za-z0-9]+/, '').toLowerCase());
});

const localeCount = incomplete.reduce((s, p) => s + p.languages.length, 0);
const scanned = activeIds.size;
const atHundred = scanned - incomplete.length - missing.length;

// --- summary ---------------------------------------------------------------
// Deliberately terse (Mary, 2026-09-21):
//  - Totals carry ONE number: projects below 100%, marked with :x: so it reads
//    as the counterpart to the :white_check_mark: at-100% line below.
//  - No "N of M projects below 100%" restatement: the header already gives M
//    and Totals already gives N.
//  - No baseline / change tracking at all. Removed on request; if it is ever
//    wanted back it needs $getWorkflowStaticData('global') to hold the previous
//    project|iso pairs, as the nightly QA report does with its key-id baseline,
//    and the first run after re-adding it can report no change.
const cleanSweep = (incomplete.length === 0);
const verified = (missing.length === 0);

let summary = '*Lokalise daily completeness check* \u2014 ' + scanned + ' active projects scanned\n\n';
summary += '*Totals*\n';
summary += ':x: Projects below 100%: ' + incomplete.length + '\n';
summary += '\n';

if (cleanSweep && verified) {
  summary += ':tada: :confetti_ball: *CONGRATULATIONS!* :confetti_ball: :tada:\n';
  summary += '*Every active project is fully translated across all ' + scanned + ' projects.*\n';
  summary += 'Every target locale at 100% \u2014 nothing outstanding, account-wide.\n';
  summary += 'Genuinely excellent work, everyone. :clap:\n';
} else if (cleanSweep) {
  summary += ':white_check_mark: Every project read is at 100% \u2014 but see the warning below before celebrating.\n';
} else {
  summary += ':white_check_mark: ' + atHundred + ' project(s) at 100%.\n';
}

if (missing.length) {
  summary += '\n:warning: in the active map but not returned by the API: ' + missing.join(', ');
}

// Slack Block Kit payload. A section carries the text; an image block carries the
// gif. An image block RENDERS the gif - posting the bare URL and hoping Slack
// unfurls it does not.
// TWO gifs, one per outcome. Neither is the nightly QA report's gif. Both were
// verified to return real GIF bytes, because media.giphy.com serves a placeholder
// gif (239321 bytes) with HTTP 200 for ANY unknown id - never trust a 200 alone
// when swapping these.
// GIF_ISSUES was chosen by Mary 2026-09-21. She supplied it as a media0 "200.gif"
// link carrying cid / ep / rid / ct query parameters; those are per-session
// tracking params, so the canonical query-less form is stored instead - same asset,
// higher resolution (649 kB vs 309 kB), and nothing that can expire.
const GIF_CLEAN = 'https://media.giphy.com/media/26u4cqiYI30juCOGY/giphy.gif';
const GIF_ISSUES = 'https://media.giphy.com/media/eImrJKnOmuBDmqXNUj/giphy.gif';

let gifUrl = null;
let gifAlt = null;
if (cleanSweep && verified) {
  gifUrl = GIF_CLEAN;
  gifAlt = 'Celebration - every active project is fully translated';
} else if (!cleanSweep) {
  gifUrl = GIF_ISSUES;
  gifAlt = 'At least one project is below 100% - details in thread';
}
// The clean-but-unverified branch deliberately gets NO gif: a warning the team
// should read does not belong under a picture.

const blocks = [{
  type: 'section',
  text: { type: 'mrkdwn', text: summary.length > 2900 ? summary.slice(0, 2897) + '...' : summary }
}];
if (gifUrl) {
  blocks.push({ type: 'image', image_url: gifUrl, alt_text: gifAlt });
}
const summaryBlocks = JSON.stringify({ blocks: blocks });

// --- thread reply: detail, percentages only --------------------------------
let threadText;
if (cleanSweep) {
  threadText = 'Nothing outstanding \u2014 all ' + scanned + ' active projects at 100%.';
} else {
  threadText = '*Projects below 100%* \u2014 ' + localeCount + ' locale' +
    (localeCount === 1 ? '' : 's') + ' below 100%\n\n' + incomplete.map(p => {
    const langStr = p.languages.map(l => l.iso + ' ' + l.progress + '%').join(', ');
    const label = String(p.name).replace(/[<>|]/g, ' ').trim();
    return '<' + p.url + '|' + label + '>\n    ' + langStr;
  }).join('\n\n') + '\n';
}

return [{ json: {
  active_count: scanned,
  incomplete_count: incomplete.length,
  locale_count: localeCount,
  missing_from_api: missing,
  celebrated: (cleanSweep && verified),
  gif_url: gifUrl,
  projects: incomplete,
  summary,
  summary_blocks: summaryBlocks,
  text: summary,
  threadText
} }];

